import sys
import EfiPy2 as EfiPy
from EfiPy2.MdePkg.IndustryStandard import Acpi, EFIPY_INDUSTRY_STRUCTURE

#
# Local APIC and x2APIC Flags Bit Field Definition (ACPI 6.5 Table 5.37 & 5.46)
#
class PROCESSOR_LOCAL_APIC_FLAGS_BITS(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Enabled",       EfiPy.UINT32, 1),
        ("OnlineCapable", EfiPy.UINT32, 1),
        ("Reserved",      EfiPy.UINT32, 30),
    ]

class PROCESSOR_LOCAL_APIC_FLAGS(EfiPy.Union):
    _fields_ = [
        ("Uint32", EfiPy.UINT32),
        ("Bits",   PROCESSOR_LOCAL_APIC_FLAGS_BITS),
    ]

#
# MPS INTI Flags Bit Field Definition (ACPI 6.5 Table 5.40)
# Used by Interrupt Source Override, NMI Source, Local APIC NMI, etc.
#
class MPS_INTI_FLAGS_BITS(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Polarity",    EfiPy.UINT16, 2),
        ("TriggerMode", EfiPy.UINT16, 2),
        ("Reserved",    EfiPy.UINT16, 12),
    ]

class MPS_INTI_FLAGS(EfiPy.Union):
    _fields_ = [
        ("Uint16", EfiPy.UINT16),
        ("Bits",   MPS_INTI_FLAGS_BITS),
    ]

#
# Processor Local APIC Structure (Type 0) with decomposed Flags
#
class EFI_ACPI_6_5_PROCESSOR_LOCAL_APIC_STRUCTURE(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Type",              EfiPy.UINT8),
        ("Length",            EfiPy.UINT8),
        ("AcpiProcessorUid",  EfiPy.UINT8),
        ("ApicId",            EfiPy.UINT8),
        ("Flags",             PROCESSOR_LOCAL_APIC_FLAGS),
    ]

#
# Interrupt Source Override Structure (Type 2) with decomposed Flags
#
class EFI_ACPI_6_5_INTERRUPT_SOURCE_OVERRIDE_STRUCTURE(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Type",                  EfiPy.UINT8),
        ("Length",                EfiPy.UINT8),
        ("Bus",                   EfiPy.UINT8),
        ("Source",                EfiPy.UINT8),
        ("GlobalSystemInterrupt", EfiPy.UINT32),
        ("Flags",                 MPS_INTI_FLAGS),
    ]

#
# Non-Maskable Interrupt Source Structure (Type 3) with decomposed Flags
#
class EFI_ACPI_6_5_NON_MASKABLE_INTERRUPT_SOURCE_STRUCTURE(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Type",                  EfiPy.UINT8),
        ("Length",                EfiPy.UINT8),
        ("Flags",                 MPS_INTI_FLAGS),
        ("GlobalSystemInterrupt", EfiPy.UINT32),
    ]

#
# Local APIC NMI Structure (Type 4) with decomposed Flags
#
class EFI_ACPI_6_5_LOCAL_APIC_NMI_STRUCTURE(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Type",              EfiPy.UINT8),
        ("Length",            EfiPy.UINT8),
        ("AcpiProcessorUid",  EfiPy.UINT8),
        ("Flags",             MPS_INTI_FLAGS),
        ("LocalApicLint",     EfiPy.UINT8),
    ]

#
# Processor Local x2APIC Structure (Type 9) with decomposed Flags
#
class EFI_ACPI_6_5_PROCESSOR_LOCAL_X2APIC_STRUCTURE(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Type",              EfiPy.UINT8),
        ("Length",            EfiPy.UINT8),
        ("Reserved",          EfiPy.UINT16),
        ("X2ApicId",          EfiPy.UINT32),
        ("Flags",             PROCESSOR_LOCAL_APIC_FLAGS),
        ("AcpiProcessorUid",  EfiPy.UINT32),
    ]

#
# Local x2APIC NMI Structure (Type 0x0A) with decomposed Flags
#
class EFI_ACPI_6_5_LOCAL_X2APIC_NMI_STRUCTURE(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Type",              EfiPy.UINT8),
        ("Length",            EfiPy.UINT8),
        ("Flags",             MPS_INTI_FLAGS),
        ("AcpiProcessorUid",  EfiPy.UINT32),
        ("LocalX2ApicLint",   EfiPy.UINT8),
        ("Reserved",          EfiPy.UINT8 * 3),
    ]

#
# Platform Interrupt Sources Structure (Type 8) with decomposed Flags
#
class EFI_ACPI_6_5_PLATFORM_INTERRUPT_SOURCES_STRUCTURE(EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Type",                         EfiPy.UINT8),
        ("Length",                       EfiPy.UINT8),
        ("Flags",                        MPS_INTI_FLAGS),
        ("InterruptType",                EfiPy.UINT8),
        ("ProcessorId",                  EfiPy.UINT8),
        ("ProcessorEid",                 EfiPy.UINT8),
        ("IoSapicVector",                EfiPy.UINT8),
        ("GlobalSystemInterrupt",        EfiPy.UINT32),
        ("PlatformInterruptSourceFlags", EfiPy.UINT32),
    ]

#
# x86-specific APIC / MADT Sub-structure Type Definition
#
X86_APIC_SUB_TABLE_MAP = {
    0x00: ("ProcessorLocalApic",         EFI_ACPI_6_5_PROCESSOR_LOCAL_APIC_STRUCTURE),
    0x01: ("IoApic",                     Acpi.EFI_ACPI_6_5_IO_APIC_STRUCTURE),
    0x02: ("InterruptSourceOverride",    EFI_ACPI_6_5_INTERRUPT_SOURCE_OVERRIDE_STRUCTURE),
    0x03: ("NonMaskableInterruptSource", EFI_ACPI_6_5_NON_MASKABLE_INTERRUPT_SOURCE_STRUCTURE),
    0x04: ("LocalApicNmi",               EFI_ACPI_6_5_LOCAL_APIC_NMI_STRUCTURE),
    0x05: ("LocalApicAddressOverride",   Acpi.EFI_ACPI_6_5_LOCAL_APIC_ADDRESS_OVERRIDE_STRUCTURE),
    0x06: ("IoSapic",                    Acpi.EFI_ACPI_6_5_IO_SAPIC_STRUCTURE),
    0x07: ("LocalSapic",                 Acpi.EFI_ACPI_6_5_PROCESSOR_LOCAL_SAPIC_STRUCTURE),
    0x08: ("PlatformInterruptSources",   EFI_ACPI_6_5_PLATFORM_INTERRUPT_SOURCES_STRUCTURE),
    0x09: ("ProcessorLocalX2Apic",       EFI_ACPI_6_5_PROCESSOR_LOCAL_X2APIC_STRUCTURE),
    0x0A: ("LocalX2ApicNmi",             EFI_ACPI_6_5_LOCAL_X2APIC_NMI_STRUCTURE),
    0x10: ("MultiProcessorWakeup",       Acpi.EFI_ACPI_6_5_MULTIPROCESSOR_WAKEUP_STRUCTURE),
}

def AcpiApicParser(ApicRaw):
    """
    Parse Multiple APIC Description Table (MADT / APIC) with continuous sub-structures
    aggregated into native ctypes Array (e.g. ProcessorLocalApic[0], ProcessorLocalApic[1])
    and decomposed bit fields for Flags (LAPIC and ISO).

    Args:
        ApicRaw (bytes/bytearray): Raw binary content of the APIC table.

    Returns:
        tuple: (ApicObj, ApicType) or (None, None) if raw data is invalid.
    """
    if ApicRaw is None:
        return None, None

    #
    # 1. Basic boundary check: Table header size
    #
    BaseHeaderType = Acpi.EFI_ACPI_6_5_MULTIPLE_APIC_DESCRIPTION_TABLE_HEADER
    BaseHeaderSize = EfiPy.sizeof(BaseHeaderType)

    RawLen = len(ApicRaw)
    if RawLen < BaseHeaderSize:
        return None, None

    InitialHeader = BaseHeaderType.from_buffer_copy(ApicRaw)
    TotalLength = InitialHeader.Header.Length

    # Check whether declared table length exceeds raw buffer or is smaller than header
    if TotalLength > RawLen or TotalLength < BaseHeaderSize:
        return None, None

    Offset = BaseHeaderSize
    ParsedEntries = []

    #
    # 2. Iterate each sub-structure and verify length
    #
    while Offset < TotalLength:
        if Offset + 2 > TotalLength:
            return None, None

        SubType   = ApicRaw[Offset]
        SubLength = ApicRaw[Offset + 1]

        # Boundary guard: return error if length < 2 or exceeds table boundary
        if SubLength < 2 or (Offset + SubLength) > TotalLength:
            return None, None

        ActualClass = None
        PrefixName  = None

        # Check if it is a supported x86 structure type
        if SubType in X86_APIC_SUB_TABLE_MAP:
            CandidateName, CandidateClass = X86_APIC_SUB_TABLE_MAP[SubType]
            # Ensure sub-structure length matches class size to avoid ctypes alignment issues
            if SubLength == EfiPy.sizeof(CandidateClass):
                PrefixName  = CandidateName
                ActualClass = CandidateClass

        # For unknown types or length mismatches, construct generic raw structure with exact SubLength
        if ActualClass is None:
            PrefixName = f"SubTable_Type0x{SubType:02X}"
            class GenericSubStructure(EFIPY_INDUSTRY_STRUCTURE):
                _fields_ = [
                    ("Type",    EfiPy.UINT8),
                    ("Length",  EfiPy.UINT8),
                    ("RawData", EfiPy.UINT8 * (SubLength - 2))
                ]
            ActualClass = GenericSubStructure

        ParsedEntries.append((PrefixName, ActualClass))
        Offset += SubLength

    # Ensure all bytes up to TotalLength are completely consumed
    if Offset != TotalLength:
        return None, None

    #
    # 3. Aggregate continuous identical sub-structures into ctypes Array
    #
    GroupedRuns = []
    for Prefix, Cls in ParsedEntries:
        if GroupedRuns and GroupedRuns[-1][0] == Prefix and GroupedRuns[-1][1] == Cls:
            GroupedRuns[-1][2] += 1
        else:
            GroupedRuns.append([Prefix, Cls, 1])

    #
    # 4. Construct composite fields
    #
    DynamicFields = list(BaseHeaderType._fields_)
    PrefixOccurrences = {}

    for Prefix, Cls, Count in GroupedRuns:
        Occ = PrefixOccurrences.get(Prefix, 0)
        PrefixOccurrences[Prefix] = Occ + 1

        # Differentiate repeated non-continuous groups with suffix (_1, _2), keep original name for first group
        FieldName = Prefix if Occ == 0 else f"{Prefix}_{Occ}"

        # Declare as ctypes Array: Cls * Count
        DynamicFields.append((FieldName, Cls * Count))

    #
    # 5. Build dynamic composite structure type and bind buffer
    #
    class ApicType(EFIPY_INDUSTRY_STRUCTURE):
        _fields_ = DynamicFields

    ApicObj = ApicType.from_buffer_copy(ApicRaw[:Offset])
    return ApicObj, ApicType

# Alias for MADT naming
AcpiMadtParser = AcpiApicParser

if __name__ == '__main__':
    from EfiPy2.Lib.StructDump import DumpStruct
    from EfiPy2.Lib.HexDump import HexDump

    if len(sys.argv) < 2:
        print("Usage: python AcpiApicParser.py <ApicBinaryFile>")
        sys.exit(-1)

    FileName = sys.argv[1]
    with open(FileName, 'rb') as f:
        RawData = bytearray(f.read())

    ApicObj, ApicType = AcpiApicParser(RawData)
    if ApicObj is None:
        print("Invalid APIC (MADT) binary.")
        sys.exit(-1)

    DumpStruct(2, ApicObj, ApicType)
    print('\n==== ACPI APIC RAW data ======')
    HexDump(RawData)
